afterEach(function (): void {
    Facade::clearResolvedInstances();
    Container::setInstance(null);
});

it('registers through its service provider and merges its config', function () {
    TestApp::boot();
    expect(config('connectors.hubspot.mode'))->toBe('auto');
    expect(config('connectors.hubspot.credentials'))->toBeArray();
});

it('fakes company_create and records it for assertSent', function () {
    TestApp::boot();
    Hubspot::fake();
    $config = [
        'properties' => [
            'order_id' => '7',
        ],
    ];
    $result = Hubspot::call('company_create', $config);

    expect($result->mode->value)->toBe('fake');
    Hubspot::assertSent('company_create', fn (array $sent): bool => $sent == $config);
    Hubspot::assertNotSent('no_such_operation');
    Hubspot::assertSentCount(1);
});

it('refuses a forged crm_event delivery before the app sees it', function () {
    $app = TestApp::boot();
    $app['router']->hubspotCrmEvent('/hooks/hubspot');
    $response = TestApp::dispatch($app, Request::create('/hooks/hubspot', 'POST', server: ['CONTENT_TYPE' => 'application/json'], content: '{"forged":true}'));

    expect($response->getStatusCode())->toBe(401);
});
